package com.codearena.controller;
import com.codearena.entity.User;import com.codearena.repository.UserRepository;import com.codearena.security.JwtService;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.http.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.web.bind.annotation.*;
import java.util.*;
@RestController public class AuthController {
 @Autowired UserRepository users; @Autowired BCryptPasswordEncoder bcrypt; @Autowired JwtService jwt;
 @PostMapping("/api/auth/register") public ResponseEntity<?> register(@RequestBody Map<String,Object> b){String name=(String)b.get("name"),email=(String)b.get("email"),password=(String)b.get("password");if(name==null||email==null||password==null)return ResponseEntity.badRequest().body(Map.of("error","All fields required"));if(users.findByEmail(email).isPresent())return ResponseEntity.badRequest().body(Map.of("error","User already exists"));User u=new User();u.setUsername(name);u.setEmail(email);u.setClerkId(email);u.setPassword(bcrypt.encode(password));users.save(u);return ResponseEntity.ok(Map.of("message","User registered successfully"));}
 @PostMapping("/api/auth/signin") public ResponseEntity<?> signin(@RequestBody Map<String,Object>b){String email=(String)b.get("email"),password=(String)b.get("password");if(email==null||password==null)return ResponseEntity.badRequest().body(Map.of("error","Email and password required"));Optional<User> found=users.findByEmail(email);if(found.isEmpty()||found.get().getPassword()==null||!bcrypt.matches(password,found.get().getPassword()))return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","Invalid credentials"));User u=found.get();String token=jwt.create(u.getId(),u.getEmail());Map<String,Object> user=Map.of("id",u.getId(),"email",u.getEmail(),"name",u.getUsername());return ResponseEntity.ok(Map.of("message","Sign in successful","token",token,"user",user));}
}
